sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np
from PIL import Image,ImageDraw,ImageFont
ROOT=LAB/'cunfa_roles_v2_20261112'
def read(n):return json.loads((ROOT/n).read_text('utf8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(n,x):(ROOT/n).write_text(json.dumps(x,ensure_ascii=False,indent=2),encoding='utf8')
def main():
 ds=read('dataset_manifest.json');res=read('results.json');assert sha(ROOT/'dataset_manifest.json')==res['protocol']['dataset_sha256'];font=lambda n:ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',n);col=np.array([[234,239,226],[192,128,40],[40,135,180]],'uint8');records=[]
 for r in ds['records']:
  row=next(q for q in res['records'] if q['id']==r['id']);image=np.load(r['path'])['image'];panels=[(image,'静态上下文输入'),(np.array(Image.open(ROOT/'references'/(r['id']+'_target.png'))),'局部参考 / 灰色未知')]
  for arm,title in [('previous_frozen','上一轮冻结模型'),('flat_roles','同数据：直接分三类'),('ink_then_role','同数据：先墨迹后角色')]:
   z=np.load(ROOT/'predictions'/(r['id']+'_'+arm+'.npz'));p=z['prediction'];raw=col[p];Image.fromarray(raw).save(ROOT/'predictions'/(r['id']+'_'+arm+'.png'));panels.append((raw,title))
  board=Image.new('RGB',(1500,470),'#f4f1e8');d=ImageDraw.Draw(board)
  for j,(im,title) in enumerate(panels):
   pimg=Image.fromarray(im);pimg.thumbnail((285,360));board.paste(pimg,(j*300+6,40));d.text((j*300+6,8),title,font=font(18),fill='#243e32')
  d.text((8,412),r['id']+'：橙=结构，蓝=皴笔。模型输出未套用参考遮罩，也不是完整笔触。',font=font(20),fill='#815238');board.save(ROOT/'predictions'/(r['id']+'_comparison.jpg'),quality=95)
  records.append(dict(**r,scores=row['scores'],input='references/'+r['id']+'_input.png',before='references/'+r['id']+'_before.png',target='references/'+r['id']+'_target.png',overlay='references/'+r['id']+'_overlay.png',comparison='predictions/'+r['id']+'_comparison.jpg',predictions={arm:'predictions/'+r['id']+'_'+arm+'.png' for arm in ['previous_frozen','flat_roles','ink_then_role']}))
 counts={split:{str(k):sum(r['reference_counts'][str(k)] for r in ds['records'] if r['split']==split) for k in range(3)} for split in ['train','heldout_source_partial_reference']};h=res['aggregates']['heldout_source_partial_reference'];b=h['ink_then_role'];a=h['flat_roles'];old=h['previous_frozen']
 improves_both=b['balanced_role_recall']>a['balanced_role_recall'] and b['paper_false_ink']<a['paper_false_ink'];best_constant=max(h['same_foreground_role_1']['balanced_role_recall'],h['same_foreground_role_2']['balanced_role_recall'])
 decision=dict(adopted=False,full_system_acceptance=False,flat_candidate_improves_over_previous_on_both_metrics=a['balanced_role_recall']>old['balanced_role_recall'] and a['paper_false_ink']<old['paper_false_ink'],split_head_beats_flat_on_both_metrics=improves_both,split_head_beats_same_foreground_constant_role=b['balanced_role_recall']>best_constant,heldout_work_count=1,heldout_observations=1,reference_is_expert_gold=False,heldout_is_blind=False,artist_independence_verified=False,reason='Only a few partial assistant references in one held-out work; does not validate full ink extent, instances, crossed/dry strokes, named cun classes or physical execution.',next_gate='More independent original artists/works with mixed roles and full local ink masks, then freeze source-level test before training.',robot_connected=False)
 write('decision.json',decision);write('report_data.json',dict(records=records,counts=counts,aggregates=res['aggregates'],decision=decision))
 title='已补三来源角色参考，完成前景与角色分开训练的对照'
 board=Image.new('RGB',(1500,1020),'#f4f1e8');d=ImageDraw.Draw(board);d.text((15,12),title,font=font(28),fill='#243e32')
 for i,ident in enumerate(['L_149_3','H_14']):board.paste(Image.open(ROOT/'predictions'/(ident+'_comparison.jpg')),(0,65+i*475))
 board.save(ROOT/'overview.jpg',quality=94)
 small=Image.new('RGB',(1260,440),'#f4f1e8');sd=ImageDraw.Draw(small)
 for j,(p,title) in enumerate([(ROOT/'references/H_14_input.png','留出局部 · 原图'),(ROOT/'predictions/H_14_previous_frozen.png','上一轮模型 · 原始角色图'),(ROOT/'predictions/H_14_flat_roles.png','本轮三分类候选 · 原始角色图')]):
  im=Image.open(p);im.thumbnail((400,305));small.paste(im,(j*420+10,60));sd.text((j*420+10,14),title,font=font(21),fill='#243e32')
 sd.text((12,365),'橙=结构，蓝=皴笔；空白误检减少，墨带仍过宽。不是完整线稿或实画效果。',font=font(22),fill='#815238');sd.text((12,403),'只检查了1件留出作品的局部参考，未经专家逐像素审核；未替换绘画版本。',font=font(19),fill='#815238');small.save(ROOT/'candidate_comparison.jpg',quality=95)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>结构与皴笔 · 三来源前景约束对照</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#243e32;font:16px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1550px;padding:28px;margin:auto}h1{font-size:30px;line-height:1.35}h2{font-size:23px;margin-top:34px}.notice{background:#fff9e8;padding:16px;border-left:5px solid #b57c3c}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card,.image{padding:12px;border:1px solid #d9d8c9;border-radius:8px;background:#fffdf7}.big{font-size:29px;font-weight:650}.panes{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.refs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}img{max-width:100%;height:auto;display:block;margin:auto;max-height:460px}select,button{font:inherit;padding:8px 12px;border-radius:6px;border:1px solid #a0b3a5;background:#fffdf7;color:#243e32;max-width:100%}button{cursor:pointer}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #d2d8c9;text-align:left}.scroll{overflow:auto}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}a{color:#236b61}small{color:#657569}.legend{display:flex;gap:18px;flex-wrap:wrap;margin:12px 0}.dot{width:13px;height:13px;display:inline-block;margin-right:6px}.warn{color:#8d4e31}code{overflow-wrap:anywhere}details{margin-top:18px}@media(max-width:1000px){.panes{grid-template-columns:repeat(3,minmax(0,1fr))}.cards,.refs{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){main{padding:15px}.panes,.cards,.refs{grid-template-columns:1fr}h1{font-size:25px}td,th{padding:6px;font-size:13px}}</style><main>
<small>2026-11-12 · 离线研究 · 未连接机械臂</small><h1>补不同来源的结构与皴笔参考，再检验“先找墨迹、后分角色”</h1><p class="notice"><b id="decision"></b><br>本轮是局部角色识别实验。彩色输出不是线稿，不代表完整笔触或已经理解披麻、斧劈等类别。所有参考均为视频支持的助手局部核查，未经专家逐像素认证。</p>
<div class="cards"><div class="card"><div class="big">2 + 1</div>训练作品来源组 + 留出来源组<br><small>训练4次观察；留出1次观察</small></div><div class="card"><div class="big" id="paperCount"></div>训练纸面核心像素<br><small>在山面内外分布，不把所有未知当背景</small></div><div class="card"><div class="big">双分支</div>墨迹检测 + 条件角色判断<br><small>同数据、同预算对照直接三分类</small></div><div class="card"><div class="big">尚未验收</div>不替换绘画版本<br><small>留出作品只有1件，原画家身份未核实</small></div></div>
<h2>1. 本轮补了什么参考</h2><p>米小鹿示范保留早期结构和短皴笔参考；刘鹏凯第37课补进同一画面的轮廓、长皴笔和纸面参考。另一段山石教学的14秒画面留出，不参与梯度更新、阈值选择或检查点选择。</p><p class="warn">刘鹏凯作品上一轮用于探索检查，本轮明确转入开发训练。留出视频在早期项目已浏览，且只能核实上传者，不能将它称为新作者盲测；不能把本轮结果与上一轮另一测试集的0.17%直接比较。</p>
<div class="controls"><label>观察 <select id="case"></select></label><span id="split"></span></div><p id="coverage"></p><div class="refs"><div class="image"><b>前一阶段 / 对齐参考</b><img id="before"></div><div class="image"><b>静态上下文输入</b><img id="refInput"></div><div class="image"><b>视频辅助局部参考</b><img id="overlay"></div></div><div class="legend"><span><i class="dot" style="background:#c08028"></i>结构</span><span><i class="dot" style="background:#2887b4"></i>皴笔</span><span><i class="dot" style="background:#5a965a"></i>核查过的纸面</span><span><i class="dot" style="background:#dad4c7"></i>待定 / 不参与损失</span></div>
<h2>2. 同图原始输出，不隐藏误判</h2><p>输入是包含山石上下文的静态局部，不按目标单笔的包围盒截取。引导走廊只用于构建参考，模型不接收前帧、差分、引导曲线、阶段时间或类别提示。两种新模型使用同样的局部背景归一化和尺度增强。</p><div class="panes"><div class="image"><b>输入</b><img id="input"></div><div class="image"><b>局部参考</b><img id="target"></div><div class="image"><b>上一轮冻结模型</b><img id="previous_frozen"></div><div class="image"><b>同数据：直接三分类</b><img id="flat_roles"></div><div class="image"><b>同数据：先墨迹后角色</b><img id="ink_then_role"></div></div><p>模型图浅绿为纸面、橙为结构、蓝为皴笔。显示所有像素的原始分类，没有套参考遮罩、没有按原图阈值二次裁剪、没有几何拼线。未知区域也显示预测，因此可检查空白误检、树木等未标区域的异常。</p>
<h2>3. 在同一个留出局部上比较</h2><div class="scroll"><table><thead><tr><th>方法</th><th>纸面误报墨迹</th><th>结构核心召回</th><th>皴笔核心召回</th><th>两类角色平均召回</th></tr></thead><tbody id="metrics"></tbody></table></div><p>分母是有参考的像素，不是整条笔画或整幅画。两类平均召回对结构与皴笔各给一半权重，避免结构像素更多掩盖皴笔失败。常量角色对照使用同一个学习到的墨迹前景，只把墨迹全部叫结构或全部叫皴笔。</p><p id="interpretation"></p><details><summary>为什么即使局部数字改善也不能宣布通过</summary><ul><li>留出只有一个作品的一个画面；未知区域没有被全部核查，纸面误报率只适用于核查过的纸面核心。</li><li>参考是视频阶段、可见墨迹与局部走廊支持的核心，不是专家完整墨带或逐笔归属。</li><li>本轮没有训练皴法名称、完整笔触实例、干笔连接、墨带宽度、落笔与收笔、笔组笔序。</li><li>视频可能经过加速或剪辑，只用于阶段/局部墨迹参考，不反推真实动作速度或下压。</li><li>构图裁剪仍由助手选择，未验证自主从整幅图定位山石。</li><li>两组各固定360步，最后一步评估；不按留出分数挑模型。原模型及旧13例失败测试均保留不变。</li></ul></details>
<h2>4. 下一步的具体入口</h2><ol><li>把参考扩大到同一块石头的完整局部墨带，同时核查细线、交叉和空白。现在的稀疏核心仍会留下大面积未约束区域。</li><li>补能确认原作者的独立作品，预先封存按作品/作者划分的测试。混合、看不清和不确定归属继续忽略。</li><li>角色验证通过后，给每条真实笔触增加实例归属、起止和完整曲线；再训练结构→成组皴笔→下一石块的依赖顺序。</li></ol><p>本轮尚未生成可下发机械臂的轨迹，也未改变当前认可的绘画版本。</p><p><a href="https://www.ganjingworld.com/video/1gc2lo9n27j5ZShwAja69iQ3N12d1c" target="_blank" rel="noreferrer">米小鹿短披麻示范</a> · <a href="https://www.ganjingworld.com/video/1h5vi07sks9KFNZ72hjMX9VrP1331c" target="_blank" rel="noreferrer">刘鹏凯第37课</a> · <a href="https://www.ganjingworld.com/video/1gc5ch0t6uo7BVAQGaZzKg2Rp1cb1c" target="_blank" rel="noreferrer">山石画法视频（原画家未核实）</a></p><p><a href="protocol.json">冻结训练协议</a> · <a href="results.json">逐例数值</a> · <a href="decision.json">采用决定</a> · <a href="verification.json">检查记录</a></p></main>
<script>let D;const $=s=>document.getElementById(s);const pct=v=>v===null?'无参考':(v*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('split').textContent=r.split==='train'?'训练作品内观察':'留出来源组局部检查';$('coverage').textContent='核心像素：纸面 '+r.reference_counts['0']+' / 结构 '+r.reference_counts['1']+' / 皴笔 '+r.reference_counts['2']+'；未知 '+r.unknown_pixels;for(let n of ['input','target','before','overlay'])$(n).src=r[n];$('refInput').src=r.input;for(let n of ['previous_frozen','flat_roles','ink_then_role'])$(n).src=r.predictions[n]}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of D.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').selectedIndex=4;$('case').onchange=show;show();$('paperCount').textContent=D.counts.train['0'].toLocaleString();let a=D.aggregates.heldout_source_partial_reference;for(let [key,name] of [['previous_frozen','上一轮冻结模型'],['flat_roles','同数据：直接三分类'],['ink_then_role','同数据：先墨迹后角色'],['same_foreground_role_1','同前景：墨迹全叫结构'],['same_foreground_role_2','同前景：墨迹全叫皴笔']]){let s=a[key],tr=document.createElement('tr');tr.innerHTML='<td>'+name+'</td>'+[s.paper_false_ink,s.recall[1],s.recall[2],s.balanced_role_recall].map(v=>'<td>'+pct(v)+'</td>').join('');$('metrics').append(tr)}let b=a.ink_then_role,f=a.flat_roles;$('decision').textContent=D.decision.split_head_beats_flat_on_both_metrics?'这一留出局部中，分开判断同时改善了角色平均召回与纸面误报；规模和参考仍不足，未通过整体验收。':'这一留出局部未证明分开判断同时改善角色与纸面误报；两组结果全部保留，未通过整体验收。';$('interpretation').textContent='分开判断相对直接三分类：角色平均召回 '+pct(f.balanced_role_recall)+' → '+pct(b.balanced_role_recall)+'；纸面误报 '+pct(f.paper_false_ink)+' → '+pct(b.paper_false_ink)+'。这些指标只对应本页这一局部参考。';window.reportReady=true});</script></html>'''
 page=page.replace("$('decision').textContent=D.decision.split_head_beats_flat_on_both_metrics?'这一留出局部中，分开判断同时改善了角色平均召回与纸面误报；规模和参考仍不足，未通过整体验收。':'这一留出局部未证明分开判断同时改善角色与纸面误报；两组结果全部保留，未通过整体验收。';", "$('decision').textContent='在这一留出局部上，本轮三分类候选较上一轮冻结模型减少了纸面误报、改善了两类角色平均召回；额外增加墨迹分支反而更差。原始输出仍有墨带过宽和交汇粘连，尚未通过整体验收。';")
 page=page.replace('常量角色对照使用同一个学习到的墨迹前景，只把墨迹全部叫结构或全部叫皴笔。','常量角色对照使用双分支模型的墨迹概率，以0.5为固定阈值，再把检出的墨迹全部叫结构或全部叫皴笔；模型自身输出仍按三类联合概率直接取最大值。')
 (ROOT/'index.html').write_text(page,encoding='utf8');print(json.dumps(dict(heldout=h,decision=decision),ensure_ascii=False),flush=True)
if __name__=='__main__':main()
